const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const c={console,TextEncoder,TextDecoder,crypto:require('node:crypto').webcrypto};c.window=c;c.globalThis=c;vm.createContext(c);for(const f of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','exercise-quality.js','core.js','planner.js','progression-engine.js','progression-paths.js','intelligence-system.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),c);
const P=c.RedaPlanner,X=c.RedaPaths,E=c.RedaProgression,options={blueprintId:'knee_pf',capacity:'high',stage:'build',trainingHistory:'rehab_experienced',equipment:'gym',goalProfile:'strength',floorOK:true,band:true};
function policy(steps){return E.compile({id:'fictional',revision:1,validFrom:'2026-09-01',validUntil:'2026-11-01',rules:{minSuccessfulDays:3,minDaysAtStep:7,maxEvidenceAgeDays:14,acceptedEffort:['easy']},steps})}
test('load, ROM and approved variant produce full separate steps without mutating source',()=>{const base=P.buildProgram(options),old=JSON.stringify(base),i=base.exercises.findIndex(x=>x.id==='leg_press');let steps=[{id:'start',label:'Start',plan:base}];for(const [change,label] of [[{prescribedLoad:'Test load'},'Belastning'],[{prescribedRange:'Test ROM'},'Rörelseomfång'],[{variantId:'single'},'Variant']]){const next=P.editExercise(steps.at(-1).plan,i,change);assert.ok(X.changes(steps.at(-1).plan,next).some(x=>x.axis===label));steps=X.append(steps,next,label,'Fiktivt kliniskt skäl.')}const p=policy(steps);assert.equal(p.steps.length,4);assert.equal(JSON.stringify(base),old);assert.equal(p.steps[3].plan.exercises[i].prescribedLoad,undefined);assert.equal(p.steps[3].plan.exercises[i].prescribedRange,undefined);assert.equal(p.steps[3].plan.exercises[i].side,'both');assert.equal(p.steps[3].plan.exercises[i].motionKey,'leg-press.single')});
test('ROM-only change binds and validates; empty/identical steps and absent rationale are refused',()=>{const p=P.buildProgram(options),steps=[{id:'a',label:'Start',plan:p}],next=P.editExercise(p,0,{prescribedRange:'Individuellt rörelseomfång'});assert.equal(policy(X.append(steps,next,'ROM','Fiktiv bedömning')).steps.length,2);assert.notEqual(E.binding(p),E.binding(next));assert.throws(()=>X.append(steps,p,'Samma','Fiktiv bedömning'));assert.throws(()=>X.append(steps,next,'ROM',''));assert.equal(c.RedaIntelligence.exercise(next,next.exercises[0]).range,'Individuellt rörelseomfång')});
test('context restrictions and unchanged goal/schedule remain binding on longer paths',()=>{const p=P.buildProgram(options),q=P.editExercise(p,0,{reps:13});q.context.equipment='home';assert.throws(()=>policy(X.append([{id:'a',label:'Start',plan:p}],q,'Nytt','Fiktiv bedömning')));const s=Array.from({length:12},(_,i)=>({id:'s'+i,label:'Steg',plan:p}));assert.throws(()=>X.append(s,q,'Tretton','Fiktiv bedömning'))});
test('diff includes independent dose axes and escapes patient authored text',()=>{const p=P.buildProgram(options),q=P.editExercise(p,0,{sets:7,reps:19,prescribedLoad:'<not markup>'}),diff=X.changes(p,q);assert.ok(diff.some(x=>x.axis==='Omgångar'));assert.ok(diff.some(x=>x.axis==='Repetitioner'));assert.ok(X.html(p,q,s=>String(s).replaceAll('<','&lt;')).includes('&lt;not markup>'))});
